<?php require_once __DIR__.'/includes/auth.php';require_user();$s=$pdo->prepare('SELECT name,email,mobile,created_at FROM users WHERE id=?');$s->execute([$_SESSION['user_id']]);$u=$s->fetch();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$mobile=trim($_POST['mobile']??'');if($m=v_name($name))$error=$m;elseif($m=v_mobile($mobile))$error=$m;else{$s=$pdo->prepare('UPDATE users SET name=?,mobile=? WHERE id=?');$s->execute([$name,normalize_mobile($mobile),$_SESSION['user_id']]);$_SESSION['user_name']=$name;flash('success','Profile updated.');redirect('profile.php');}}$pageTitle='My profile';require __DIR__.'/includes/header.php'; ?><section class="section section-soft"><div class="container"><div class="auth-card mx-auto"><span class="eyebrow">Account settings</span><h1 class="h2 mt-3">My profile</h1><?php if($error): ?><div class="alert alert-danger"><?=e($error)?></div><?php endif; ?><form method="post" data-validate novalidate><?=csrf_field()?><div class="mb-3"><label class="form-label" for="name">Full name</label><input class="form-control" id="name" name="name" required minlength="2" maxlength="60" data-rule="name" value="<?=e($_POST['name']??$u['name'])?>"></div><div class="mb-3"><label class="form-label">Email address</label><input class="form-control" value="<?=e($u['email'])?>" disabled><div class="form-text">Email changes are not enabled in this demo.</div></div><div class="mb-4"><label class="form-label" for="mobile">Mobile number</label><input class="form-control" id="mobile" type="tel" name="mobile" required maxlength="16" data-rule="mobile" value="<?=e($_POST['mobile']??$u['mobile'])?>"></div><button class="btn btn-primary">Save changes</button></form></div></div></section><?php require __DIR__.'/includes/footer.php'; ?>
